{"CommandLine":"$bytes = [System.IO.File]::ReadAllBytes("C:\Program Files\Allen & Heath\SQ MixPad 1.6.1\SQ MixPad.exe")
$sq5 = [System.IO.File]::ReadAllBytes("C:\Users\brazi\.gemini\antigravity-cli\brain\7c40d475-4f8e-4ff9-9d8a-99008f2e1cda\SQ5.DAT")
$tableRaw = 0x28F11E - 0x1A00
$table = New-Object uint32[] 256
for ($i = 0; $i -lt 256; $i++) {
    $table[$i] = [BitConverter]::ToUInt32($bytes, $tableRaw + $i * 4)
}
$crc = [uint32]0
for ($i = 0x14; $i -lt 0x1FFFC; $i++) {
    $crc = $crc -bxor [uint32]0xFFFFFFFF
    $idx = ($crc -bxor $sq5[$i]) -band 0xFF
    $crc = ($crc -shr 8) -bxor $table[$idx]
    $crc = $crc -bxor [uint32]0xFFFFFFFF
}
$expected = [BitConverter]::ToUInt32($sq5, 0x1FFFC)
Write-Host ("Computed CRC: 0x{0:X8} | Expected in SQ5.DAT: 0x{1:X8}" -f $crc, $expected)

Write-Host "=== SaveShowFileToFile (0x110900 .. 0x110B20) ==="
for ($p = 0x110900; $p -lt 0x110B20; $p += 16) {
    $hex = ($bytes[$p..($p+15)] | ForEach-Object { $_.ToString("X2") }) -join " "
    Write-Host ("0x{0:X6} (RVA 0x{1:X6}): {2}" -f $p, ($p + 0xC00), $hex)
}","WaitMsBeforeAsync":5000,"toolSummary":"Verify CRC32 on SQ5.DAT and inspect SaveShowFileToFile machine code"}
